def task_func(n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer.")
    # If n is 1 there are no possible pairs
    if n < 2:
        return []

    result = []
    # Generate all unique pairs (i, j) with i < j ranging from 1 to n
    for i in range(1, n):
        for j in range(i + 1, n + 1):
            result.append((i, j))

    return result

